describe('Image Alt Text Accessibility', () => {
  beforeEach(() => {
    cy.visit('/images');
  });

  it('should display descriptive alt text for all images', () => {
    cy.get('[data-testid="image-container"]').should('be.visible');
    cy.get('[data-testid="image-1"]').should('be.visible');
    cy.get('[data-testid="image-1"]').should('have.attr', 'alt', 'A beautiful sunset over the mountains');
    cy.get('[data-testid="image-2"]').should('be.visible');
    cy.get('[data-testid="image-2"]').should('have.attr', 'alt', 'A group of people laughing at a comedy show');
    cy.get('[data-testid="image-3"]').should('be.visible');
    cy.get('[data-testid="image-3"]').should('have.attr', 'alt', 'A close-up of a cat with whiskers');
    cy.get('[data-testid="image-4"]').should('be.visible');
    cy.get('[data-testid="image-4"]').should('have.attr', 'alt', 'A detailed illustration of a human heart');
  });

  it('should not display empty or generic alt text for images', () => {
    cy.get('[data-testid="image-5"]').should('be.visible');
    cy.get('[data-testid="image-5"]').should('have.attr', 'alt', '');
    cy.get('[data-testid="image-6"]').should('be.visible');
    cy.get('[data-testid="image-6"]').should('have.attr', 'alt', '');
    cy.get('[data-testid="image-7"]').should('be.visible');
    cy.get('[data-testid="image-7"]').should('have.attr', 'alt', '');
    cy.get('[data-testid="image-8"]').should('be.visible');
    cy.get('[data-testid="image-8"]').should('have.attr', 'alt', '');
  });
});
